"""API Router for Order management."""

from typing import List
from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session

from backend.database import get_db
from backend.models.order import Order, OrderItem
from backend.schemas.order import (
    Order as OrderSchema,
    OrderCreate,
    OrderUpdate,
)
from backend.models.enums import OrderStatus

router = APIRouter()


@router.post("/", response_model=OrderSchema, status_code=status.HTTP_201_CREATED)
def create_order(order_in: OrderCreate, db: Session = Depends(get_db)):
    """Create a new order with items."""
    db_order = Order(
        user_id=order_in.user_id,
        payment_method=order_in.payment_method.value,
        status=OrderStatus.PENDING.value,
    )

    for item_data in order_in.items:
        db_item = OrderItem(
            product_id=item_data.product_id,
            product_name=item_data.product_name,
            quantity=item_data.quantity,
            price=item_data.price,
        )
        db_order.items.append(db_item)

    db_order.update_total()

    db.add(db_order)
    db.commit()
    db.refresh(db_order)

    return db_order


@router.get("/{order_id}", response_model=OrderSchema)
def read_order(order_id: int, db: Session = Depends(get_db)):
    """Get a specific order by ID."""
    db_order = db.query(Order).filter(Order.id == order_id).first()
    if db_order is None:
        raise HTTPException(status_code=404, detail="Order not found")
    return db_order


@router.get("/", response_model=List[OrderSchema])
def list_orders(user_id: str = None, db: Session = Depends(get_db)):
    """List all orders, optionally filtered by user_id."""
    query = db.query(Order)
    if user_id:
        query = query.filter(Order.user_id == user_id)
    return query.all()


@router.put("/{order_id}", response_model=OrderSchema)
def update_order(order_id: int, order_update: OrderUpdate, db: Session = Depends(get_db)):
    """Update an existing order's status or items."""
    db_order = db.query(Order).filter(Order.id == order_id).first()
    if db_order is None:
        raise HTTPException(status_code=404, detail="Order not found")

    if order_update.status:
        db_order.status = order_update.status.value

    if order_update.items is not None:
        # Clear existing items and add new ones
        db_order.items = []
        for item_data in order_update.items:
            db_item = OrderItem(
                product_id=item_data.product_id,
                product_name=item_data.product_name,
                quantity=item_data.quantity,
                price=item_data.price,
            )
            db_order.items.append(db_item)
        db_order.update_total()

    db.commit()
    db.refresh(db_order)
    return db_order


@router.delete("/{order_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_order(order_id: int, db: Session = Depends(get_db)):
    """Delete an order."""
    db_order = db.query(Order).filter(Order.id == order_id).first()
    if db_order is None:
        raise HTTPException(status_code=404, detail="Order not found")

    db.delete(db_order)
    db.commit()
    return None
